INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(100, 'appear', '/əˈpɪər/', 'verb', '{"zh-TW":["出現；似乎","出現；似乎；看起來"],"en":["to become visible","to seem or give the impression","to become visible; to seem"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"pear","meaning":"be visible (可見)"},"logic":"朝向可見，即「出現」。"}', 'appear to be / appear on/in; appear to be / appear in; appear to be / it appears that', '[{"en":"The error appears to have been corrected.","zh-TW":"這個錯誤似乎已被更正。"},{"en":"New opportunities appear as the market evolves.","zh-TW":"隨著市場發展，新機會不斷出現。"},{"en":"Stars appear at night.","zh-TW":"星星在夜晚出現。"},{"en":"He appears to be happy.","zh-TW":"他看起來很開心。"},{"en":"A new store appeared on our street.","zh-TW":"一家新店出現在我們的街上。"},{"en":"He appears to be very busy.","zh-TW":"他看起來非常忙碌。"}]', '{"noun":"appearance","adjective":"apparent","adverb":"apparently"}', NULL, 2, 100),
(101, 'apple', '/ˈæpl/', 'noun', '{"zh-TW":["蘋果"],"en":["a round fruit with red, green, or yellow skin"]}', NULL, 'apple pie / apple juice', '[{"en":"An apple a day keeps the doctor away.","zh-TW":"一天一蘋果，醫生遠離我。"},{"en":"She bought some apples at the market.","zh-TW":"她在市場買了一些蘋果。"}]', NULL, NULL, 2, 101),
(102, 'applicable', '/əˈplɪkəbl/', 'adjective', '{"zh-TW":["適用的；可應用的"],"en":["relevant or appropriate to a situation"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠朝向應用的，即「適用的」。"}', 'applicable to / where applicable', '[{"en":"This discount is applicable to orders over $100.","zh-TW":"此折扣適用於超過100美元的訂單。"},{"en":"Please fill in all applicable fields on the form.","zh-TW":"請填寫表格上所有適用的欄位。"}]', '{"noun":"applicability"}', NULL, 4, 102),
(103, 'applicant', '/ˈæplɪkənt/', 'noun', '{"zh-TW":["申請人；應徵者"],"en":["a person who applies for something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ant","meaning":"person who (…的人)"},"logic":"朝向應用的人，即「申請人」。"}', 'job applicant / successful applicant', '[{"en":"We received over 200 applicants for the position.","zh-TW":"我們收到了超過200位該職位的應徵者。"},{"en":"Successful applicants will be notified by email.","zh-TW":"錄取者將以電子郵件通知。"}]', '{"noun":"application","verb":"apply"}', NULL, 3, 103),
(104, 'application', '/ˌæplɪˈkeɪʃən/', 'noun', '{"zh-TW":["應用程式；申請"],"en":["a computer program; a formal request"]}', NULL, 'mobile application / job application', '[{"en":"Download the application from the store.","zh-TW":"從商店下載這個應用程式。"},{"en":"I submitted my job application.","zh-TW":"我提交了工作申請。"}]', '{"verb":"apply","noun2":"applicant"}', NULL, 4, 104),
(105, 'apply', '/əˈplaɪ/', 'verb', '{"zh-TW":["申請；應用"],"en":["to make a formal request","to put into operation or use"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"ply","meaning":"fold (折疊/靠近)"},"logic":"朝向靠近，即「申請、應用」。"}', 'apply for a job / apply knowledge', '[{"en":"She applied for the marketing manager position.","zh-TW":"她應徵了行銷經理職位。"},{"en":"Students learn how to apply theory to practice.","zh-TW":"學生學習如何將理論應用於實踐。"}]', '{"noun":"application","adjective":"applicable"}', NULL, 2, 105),
(106, 'appoint', '/əˈpɔɪnt/', 'verb', '{"zh-TW":["任命；指定"],"en":["to officially choose someone for a position"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"point","meaning":"point (指)"},"logic":"朝向指定某人，即「任命」。"}', 'appoint a director/representative', '[{"en":"The board appointed a new chief financial officer.","zh-TW":"董事會任命了新的財務長。"},{"en":"She was appointed to lead the project team.","zh-TW":"她被指定領導專案團隊。"}]', '{"noun":"appointment"}', NULL, 3, 106),
(107, 'appraise', '/əˈpreɪz/', 'verb', '{"zh-TW":["評估；鑑定"],"en":["to assess the value or quality of something"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"praise","meaning":"price/value (價值)"},"logic":"朝向評定價值，即「評估」。"}', 'appraise performance/property/value', '[{"en":"The property was appraised at $1.2 million.","zh-TW":"該房產被估價為120萬美元。"},{"en":"Managers appraise staff performance annually.","zh-TW":"經理每年評估員工績效。"}]', '{"noun":"appraisal"}', NULL, 3, 107),
(108, 'appreciate', '/əˈpriːʃieɪt/', 'verb', '{"zh-TW":["感謝；欣賞","增值"],"en":["to be grateful for","to increase in value"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"preci","meaning":"price/value (價值)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"朝向認識價值，即「感謝、增值」。"}', 'appreciate support/help / appreciate in value', '[{"en":"We appreciate your continued support.","zh-TW":"我們感謝您持續的支持。"},{"en":"The property has appreciated significantly over time.","zh-TW":"該房產隨著時間大幅增值。"}]', '{"noun":"appreciation"}', NULL, 4, 108),
(109, 'approach', '/əˈprəʊtʃ/', 'noun', '{"zh-TW":["方法；途徑","接近"],"en":["a way of dealing with something","the act of coming near"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proach","meaning":"near (靠近)"},"logic":"朝向靠近，即「接近、方法」。"}', 'approach to / new approach', '[{"en":"We need a fresh approach to this problem.","zh-TW":"我們需要一個解決此問題的新方法。"},{"en":"The deadline is approaching rapidly.","zh-TW":"截止日期正在迅速逼近。"}]', '{"adjective":"approachable"}', NULL, 3, 109),
(110, 'appropriate', '/əˈprəʊpriət/', 'adjective', '{"zh-TW":["適當的；恰當的","適當的"],"en":["suitable or proper in the circumstances","suitable or proper for the circumstances"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"propri","meaning":"own (自己的)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向自己所有的，即「適當的」。"}', 'appropriate measures/behavior/response; appropriate behavior / appropriate response', '[{"en":"Please dress in appropriate business attire.","zh-TW":"請穿著適當的商務服裝。"},{"en":"The manager took appropriate action.","zh-TW":"經理採取了適當的行動。"},{"en":"Jeans are not appropriate for a formal dinner.","zh-TW":"牛仔褲不適合正式晚宴。"},{"en":"Please wear appropriate clothing.","zh-TW":"請穿著合適的服裝。"}]', '{"adverb":"appropriately","noun":"appropriateness"}', NULL, 4, 110),
(111, 'approve', '/əˈpruːv/', 'verb', '{"zh-TW":["批准；核准","贊成"],"en":["to officially agree to or accept","to believe that something is good"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"prove","meaning":"test/good (驗證/好)"},"logic":"朝向好的，即「批准」。"}', 'approve a request/budget/plan', '[{"en":"The board approved the annual budget.","zh-TW":"董事會批准了年度預算。"},{"en":"The proposal was approved unanimously.","zh-TW":"該提案被一致通過。"}]', '{"noun":"approval"}', NULL, 3, 111),
(112, 'approximate', '/əˈprɒksɪmət/', 'adjective', '{"zh-TW":["大約的；近似的"],"en":["close to the actual but not completely exact"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"proxim","meaning":"nearest (最近)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"朝向最近的，即「近似的」。"}', 'approximate cost/time/value', '[{"en":"The approximate cost of the project is $500,000.","zh-TW":"該專案的大約成本為50萬美元。"},{"en":"Can you give me an approximate delivery date?","zh-TW":"你能給我一個大約的交貨日期嗎？"}]', '{"adverb":"approximately","noun":"approximation"}', NULL, 4, 112),
(113, 'approximately', '/əˈprɒksɪmətli/', 'adverb', '{"zh-TW":["大約"],"en":["close to an exact amount but not completely accurate"]}', '{"prefix":{"text":"ap-","meaning":"to (朝向)"},"root":{"text":"proxim","meaning":"near (接近)"},"suffix":{"text":"-ately","meaning":"in manner of (以…方式)"},"logic":"以接近的方式，即「大約」。"}', 'approximately 100 / takes approximately', '[{"en":"The project will take approximately six months.","zh-TW":"這個專案大約需要六個月。"},{"en":"Approximately 200 people attended the event.","zh-TW":"大約200人參加了活動。"}]', '{"adjective":"approximate","verb":"approximate","noun":"approximation"}', NULL, 5, 113),
(114, 'architect', '/ˈɑːrkɪtekt/', 'noun', '{"zh-TW":["建築師"],"en":["a person who designs buildings"]}', '{"prefix":{"text":"archi-","meaning":"chief (首席)"},"root":{"text":"tect","meaning":"builder (建造者)"},"logic":"首席建造者，即「建築師」。"}', 'architect firm / landscape architect', '[{"en":"The architect designed a modern office building.","zh-TW":"建築師設計了一棟現代辦公大樓。"},{"en":"She hired an architect to redesign her home.","zh-TW":"她聘請建築師重新設計她的房子。"}]', '{"noun":"architecture","adjective":"architectural"}', NULL, 3, 114),
(115, 'area', '/ˈɛriə/', 'noun', '{"zh-TW":["區域；面積"],"en":["a particular part of a place or subject"]}', NULL, 'in the area / area of expertise', '[{"en":"This area is known for its food.","zh-TW":"這個地區以美食聞名。"},{"en":"What''s the area of this room?","zh-TW":"這個房間的面積是多少？"}]', NULL, NULL, 1, 115),
(116, 'arise', '/əˈraɪz/', 'verb', '{"zh-TW":["出現；產生","出現；發生"],"en":["to come into being or to come to attention","to come into being; to occur"]}', '{"prefix":{"text":"a-","meaning":"up (向上)"},"root":{"text":"rise","meaning":"rise (升起)"},"logic":"升起來，即「出現」。"}', 'arise from / problems arise; problems arise / arise from / should the need arise', '[{"en":"Several issues arose during the negotiation.","zh-TW":"談判期間出現了幾個問題。"},{"en":"Opportunities may arise from this partnership.","zh-TW":"這個合作關係可能產生機會。"},{"en":"Unexpected problems arose during the project.","zh-TW":"專案期間出現了意料之外的問題。"},{"en":"Conflicts can arise from misunderstandings.","zh-TW":"衝突可能源於誤解。"}]', NULL, NULL, 2, 116),
(117, 'arm', '/ɑːrm/', 'noun', '{"zh-TW":["手臂；武器","手臂；武裝"],"en":["the body part from shoulder to hand","the body part between shoulder and hand; to supply with weapons"]}', NULL, 'arm in arm / open arms; arm in arm / armed with', '[{"en":"She broke her arm skiing.","zh-TW":"她滑雪時摔斷了手臂。"},{"en":"They welcomed us with open arms.","zh-TW":"他們張開雙臂歡迎我們。"},{"en":"She broke her arm in the accident.","zh-TW":"她在事故中摔斷了手臂。"},{"en":"The security guard was armed.","zh-TW":"保全人員有武裝。"}]', '{"noun":"armament","adjective":"armed, unarmed"}', NULL, 1, 117),
(118, 'army', '/ˈɑːrmi/', 'noun', '{"zh-TW":["軍隊；陸軍"],"en":["the military land forces of a country"]}', NULL, 'join the army / army base', '[{"en":"He joined the army at 18.","zh-TW":"他18歲參軍。"},{"en":"The army was deployed overseas.","zh-TW":"軍隊被部署到海外。"}]', NULL, NULL, 1, 118),
(119, 'around', '/əˈraʊnd/', 'preposition', '{"zh-TW":["周圍；大約"],"en":["on all sides of; approximately"]}', NULL, 'around the world / look around', '[{"en":"There are trees around the house.","zh-TW":"房子周圍有樹。"},{"en":"It costs around fifty dollars.","zh-TW":"大約花費五十美元。"}]', NULL, NULL, 2, 119),
(120, 'arrange', '/əˈreɪndʒ/', 'verb', '{"zh-TW":["安排；籌備"],"en":["to plan or organize something in advance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"range","meaning":"rank/row (排列)"},"logic":"朝向排列，即「安排」。"}', 'arrange a meeting/event/delivery', '[{"en":"I''ll arrange a meeting with the client for next week.","zh-TW":"我會安排下週與客戶的會議。"},{"en":"Transportation has been arranged for all attendees.","zh-TW":"已為所有出席者安排了交通。"}]', '{"noun":"arrangement"}', NULL, 3, 120),
(121, 'arrive', '/əˈraɪv/', 'verb', '{"zh-TW":["到達；抵達"],"en":["to reach a destination","to reach a place after traveling"]}', NULL, 'arrive at / arrive on time; arrive at/in + 地點', '[{"en":"The shipment will arrive tomorrow.","zh-TW":"貨物明天會到達。"},{"en":"Please arrive 10 minutes early.","zh-TW":"請提前10分鐘到達。"},{"en":"The flight arrives at 3 PM.","zh-TW":"班機下午三點抵達。"},{"en":"We arrived in Tokyo yesterday.","zh-TW":"我們昨天到達東京。"}]', '{"verb":"arrive","noun":"arrival"}', NULL, 2, 121),
(122, 'arrogant', '/ˈærəɡənt/', 'adjective', '{"zh-TW":["傲慢的"],"en":["having an exaggerated sense of one''s importance"]}', '{"prefix":{"text":"ar-","meaning":"toward (朝向)"},"root":{"text":"rog","meaning":"ask/claim (要求)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"對自己提出過高要求的，即「傲慢的」。"}', 'arrogant attitude / arrogant behavior', '[{"en":"His arrogant attitude made him unpopular.","zh-TW":"他傲慢的態度使他不受歡迎。"},{"en":"Don''t be so arrogant about your achievements.","zh-TW":"不要對你的成就如此傲慢。"}]', '{"noun":"arrogance"}', NULL, 3, 122),
(123, 'art', '/ɑːrt/', 'noun', '{"zh-TW":["藝術；美術"],"en":["the creation of beautiful or meaningful things"]}', NULL, 'work of art / art gallery', '[{"en":"She studies art at university.","zh-TW":"她在大學學藝術。"},{"en":"This painting is a true work of art.","zh-TW":"這幅畫是真正的藝術品。"}]', '{"noun":"artist","adjective":"artistic"}', NULL, 1, 123),
(124, 'artifact', '/ˈɑːrtɪfækt/', 'noun', '{"zh-TW":["文物；人工製品"],"en":["an object made by a human, especially one of historical interest"]}', '{"root":{"text":"arti","meaning":"skill (技藝)"},"suffix":{"text":"fact","meaning":"made (製造)"},"logic":"用技藝製造的東西，即「工藝品」。"}', 'ancient artifact / cultural artifact', '[{"en":"The museum displays artifacts from ancient Egypt.","zh-TW":"博物館展示古埃及文物。"},{"en":"Archaeologists discovered several artifacts at the site.","zh-TW":"考古學家在遺址發現了數件文物。"}]', NULL, NULL, 3, 124),
(125, 'artificial', '/ˌɑːrtɪˈfɪʃəl/', 'adjective', '{"zh-TW":["人工的；人造的"],"en":["made by people; not natural","made by humans rather than occurring naturally"]}', '{"root":{"text":"arti","meaning":"skill/craft (技藝)"},"suffix":{"text":"-ficial","meaning":"making (製造)"},"logic":"用技藝製造的，即「人工的」。"}', 'artificial intelligence / artificial flavor', '[{"en":"Artificial intelligence is changing the world.","zh-TW":"人工智慧正在改變世界。"},{"en":"The flowers are artificial.","zh-TW":"這些花是人造的。"},{"en":"The lake is artificial, not natural.","zh-TW":"這個湖是人工的，不是天然的。"},{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多產業。"}]', '{"adverb":"artificially"}', NULL, 4, 125),
(126, 'ask', '/ɑːsk/', 'verb', '{"zh-TW":["詢問；要求；邀請"],"en":["to say something to get an answer; to request"]}', NULL, 'ask for / ask sb to do sth / ask about', '[{"en":"Can I ask you a question?","zh-TW":"我可以問你一個問題嗎？"},{"en":"She asked for a raise.","zh-TW":"她要求加薪。"}]', NULL, NULL, 1, 126),
(127, 'aspect', '/ˈæspekt/', 'noun', '{"zh-TW":["方面；層面"],"en":["a particular part or feature of something"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"spect","meaning":"look (看)"},"logic":"從某個方向看過去的面向，即「方面」。"}', 'important aspect / every aspect / key aspect', '[{"en":"We need to consider every aspect of the problem.","zh-TW":"我們需要考慮問題的每個方面。"},{"en":"Safety is the most important aspect of the job.","zh-TW":"安全是這份工作最重要的面向。"}]', NULL, NULL, 2, 127),
(128, 'assemble', '/əˈsembl/', 'verb', '{"zh-TW":["組裝；集合"],"en":["to fit together the parts of","to come together in one place","to put together the parts of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"semble","meaning":"together (一起)"},"logic":"朝向一起，即「組裝、集合」。"}', 'assemble a team/product/parts; assemble a team / assemble furniture', '[{"en":"Workers assemble the components on the factory floor.","zh-TW":"工人在工廠車間組裝零件。"},{"en":"The committee assembled to discuss the proposal.","zh-TW":"委員會集合討論該提案。"},{"en":"Workers assemble the products on the factory floor.","zh-TW":"工人在工廠樓層組裝產品。"},{"en":"The team assembled in the conference room.","zh-TW":"團隊在會議室集合。"}]', '{"noun":"assembly"}', NULL, 3, 128),
(129, 'assert', '/əˈsɜːrt/', 'verb', '{"zh-TW":["斷言；主張"],"en":["to state something clearly and firmly"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sert","meaning":"join/bind (結合)"},"logic":"朝向牢固結合的聲明，即「斷言」。"}', 'assert rights/authority/claims', '[{"en":"The company asserted its right to the patent.","zh-TW":"公司主張其專利權。"},{"en":"She asserted that the data was accurate.","zh-TW":"她斷言資料是準確的。"}]', '{"noun":"assertion","adjective":"assertive"}', NULL, 2, 129),
(130, 'assess', '/əˈses/', 'verb', '{"zh-TW":["評估；估算"],"en":["to evaluate or estimate the nature or quality of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sess","meaning":"sit (坐)"},"logic":"坐下來朝向審視，即「評估」。"}', 'assess risk/damage/performance', '[{"en":"We need to assess the potential risks before investing.","zh-TW":"投資前我們需要評估潛在風險。"},{"en":"The damage was assessed at $2 million.","zh-TW":"損失估計為200萬美元。"}]', '{"noun":"assessment"}', NULL, 2, 130),
(131, 'assign', '/əˈsaɪn/', 'verb', '{"zh-TW":["分配；指派"],"en":["to give someone a particular job or task"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sign","meaning":"mark (標記)"},"logic":"朝向標記某人做某事，即「指派」。"}', 'assign a task/role/responsibility', '[{"en":"The manager assigned the task to the new employee.","zh-TW":"經理將任務分配給新員工。"},{"en":"Each team member was assigned a specific role.","zh-TW":"每位團隊成員被指派了特定角色。"}]', '{"noun":"assignment"}', NULL, 2, 131),
(132, 'assignment', '/əˈsaɪnmənt/', 'noun', '{"zh-TW":["作業；任務"],"en":["a task given as part of a job or studies"]}', NULL, 'homework assignment / complete an assignment', '[{"en":"The assignment is due on Friday.","zh-TW":"作業週五到期。"},{"en":"She completed all her assignments on time.","zh-TW":"她按時完成了所有作業。"}]', '{"verb":"assign"}', NULL, 4, 132),
(133, 'assist', '/əˈsɪst/', 'verb', '{"zh-TW":["協助；幫助"],"en":["to help or give support to someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"站在旁邊支持，即「協助」。"}', 'assist with / assist in doing', '[{"en":"Our team will assist you with the transition.","zh-TW":"我們的團隊將協助您完成過渡。"},{"en":"Can I assist you in finding what you need?","zh-TW":"我能幫您找到您需要的東西嗎？"}]', '{"noun":"assistance","noun2":"assistant"}', NULL, 2, 133),
(134, 'associate', '/əˈsəʊsieɪt/', 'verb', '{"zh-TW":["聯想；關聯","交往"],"en":["to connect in one''s mind","to spend time with someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"soci","meaning":"companion (夥伴)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為夥伴，即「關聯」。"}', 'associate with / be associated with', '[{"en":"Customers associate the brand with quality.","zh-TW":"顧客將該品牌與品質聯繫在一起。"},{"en":"High stress is associated with health problems.","zh-TW":"高壓力與健康問題有關。"}]', '{"noun":"association"}', NULL, 3, 134),
(135, 'assume', '/əˈsjuːm/', 'verb', '{"zh-TW":["假設；承擔"],"en":["to suppose to be true without proof","to take on responsibility"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"朝向拿取（未證實的），即「假設」。"}', 'assume responsibility/role/risk', '[{"en":"Let''s assume the project will take six months.","zh-TW":"我們假設這個專案需要六個月。"},{"en":"She assumed the role of department head.","zh-TW":"她承擔了部門主管的角色。"}]', '{"noun":"assumption"}', NULL, 2, 135),
(136, 'assure', '/əˈʃʊər/', 'verb', '{"zh-TW":["保證；使確信","向…保證；確保"],"en":["to tell someone confidently to remove doubt","to tell someone confidently that something is true"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"朝向使人確定，即「保證」。"}', 'assure sb that / rest assured; assure someone that / rest assured / I assure you', '[{"en":"I assure you that the issue will be resolved promptly.","zh-TW":"我向您保證問題將盡快解決。"},{"en":"Rest assured, your data is secure.","zh-TW":"請放心，您的資料是安全的。"},{"en":"I assure you the problem will be fixed.","zh-TW":"我向你保證問題會被解決。"},{"en":"Rest assured, your data is safe.","zh-TW":"請放心，你的資料是安全的。"}]', '{"noun":"assurance","adjective":"assured"}', NULL, 2, 136),
(137, 'athlete', '/ˈæθliːt/', 'noun', '{"zh-TW":["運動員"],"en":["a person who is good at sports"]}', NULL, 'professional athlete / athlete''s performance', '[{"en":"She is a talented athlete.","zh-TW":"她是一位有天賦的運動員。"},{"en":"The athlete broke the world record.","zh-TW":"那位運動員打破了世界紀錄。"}]', '{"adjective":"athletic","noun2":"athletics"}', NULL, 3, 137),
(138, 'atmosphere', '/ˈætməsfɪr/', 'noun', '{"zh-TW":["大氣層；氣氛"],"en":["the layer of gases around the earth","the mood or feeling of a place"]}', '{"root":{"text":"atmos","meaning":"vapor (蒸氣)"},"suffix":{"text":"sphere","meaning":"ball (球)"},"logic":"蒸氣包圍的球體，即「大氣層」。"}', 'earth''s atmosphere / friendly atmosphere', '[{"en":"The atmosphere at the party was lively.","zh-TW":"派對的氣氛很活絡。"},{"en":"Pollution is damaging the atmosphere.","zh-TW":"汙染正在破壞大氣層。"}]', '{"adjective":"atmospheric"}', NULL, 4, 138),
(139, 'attach', '/əˈtætʃ/', 'verb', '{"zh-TW":["附上；連接"],"en":["to fasten or join one thing to another"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tach","meaning":"stake/fasten (釘住)"},"logic":"朝向釘住，即「附上」。"}', 'attach a file/document/label', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看附在此電子郵件中的報告。"},{"en":"Attach the receipt to your expense claim.","zh-TW":"請將收據附在您的報銷申請上。"}]', '{"noun":"attachment"}', NULL, 2, 139),
(140, 'attack', '/əˈtæk/', 'noun', '{"zh-TW":["攻擊；發作"],"en":["an act of violence against someone"]}', NULL, 'heart attack / under attack', '[{"en":"The city was under attack.","zh-TW":"城市遭受了攻擊。"},{"en":"He suffered a heart attack.","zh-TW":"他心臟病發作了。"}]', '{"verb":"attack","noun2":"attacker"}', NULL, 2, 140),
(141, 'attain', '/əˈteɪn/', 'verb', '{"zh-TW":["達到；獲得"],"en":["to succeed in achieving something after effort"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有，即「達到」。"}', 'attain a goal/level/standard', '[{"en":"Few companies attain such high customer satisfaction ratings.","zh-TW":"很少有公司達到如此高的客戶滿意度。"},{"en":"He attained the rank of senior vice president.","zh-TW":"他達到了資深副總裁的職位。"}]', '{"adjective":"attainable","noun":"attainment"}', NULL, 2, 141),
(142, 'attempt', '/əˈtempt/', 'verb', '{"zh-TW":["嘗試；企圖"],"en":["to try to do something, especially difficult","to try to do something"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tempt","meaning":"try (嘗試)"},"logic":"朝向嘗試，即「企圖」。"}', 'attempt to do / make an attempt; attempt to / first attempt / make an attempt', '[{"en":"The company attempted to enter the European market.","zh-TW":"公司嘗試進入歐洲市場。"},{"en":"Several attempts were made to resolve the dispute.","zh-TW":"多次嘗試解決爭端。"},{"en":"He attempted to climb the mountain alone.","zh-TW":"他嘗試獨自攀登那座山。"},{"en":"She passed the exam on her first attempt.","zh-TW":"她第一次嘗試就通過了考試。"}]', '{"noun":"attempt"}', NULL, 3, 142),
(143, 'attend', '/əˈtend/', 'verb', '{"zh-TW":["出席；參加","照料"],"en":["to be present at an event","to deal with or give attention to"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tend","meaning":"stretch (延伸)"},"logic":"朝向延伸注意力，即「出席」。"}', 'attend a meeting/conference/event', '[{"en":"Over 500 delegates attended the annual conference.","zh-TW":"超過500位代表出席了年度會議。"},{"en":"Please confirm whether you will attend.","zh-TW":"請確認您是否會出席。"}]', '{"noun":"attendance","noun2":"attendee"}', NULL, 2, 143),
(144, 'attention', '/əˈtɛnʃən/', 'noun', '{"zh-TW":["注意力；關注","注意；關注"],"en":["the act of concentrating on something","the act of thinking about or watching something carefully"]}', NULL, 'pay attention / draw attention to; pay attention to / attract/draw attention', '[{"en":"Pay attention to the safety guidelines.","zh-TW":"請注意安全指南。"},{"en":"The report drew attention to the issue.","zh-TW":"報告引起了人們對該問題的關注。"},{"en":"Please pay attention to the instructions.","zh-TW":"請注意指示。"},{"en":"The advertisement attracted a lot of attention.","zh-TW":"這則廣告引起了很多關注。"}]', '{"noun":"attention","adjective":"attentive","adverb":"attentively"}', NULL, 3, 144),
(145, 'attitude', '/ˈætɪtjuːd/', 'noun', '{"zh-TW":["態度；看法"],"en":["a settled way of thinking or feeling about something"]}', '{"root":{"text":"apt","meaning":"fit (適合)"},"suffix":{"text":"-itude","meaning":"state (狀態)"},"logic":"適合的狀態展現，即「態度」。"}', 'positive/negative attitude / attitude toward', '[{"en":"A positive attitude is valued in the workplace.","zh-TW":"工作場所重視積極的態度。"},{"en":"Her attitude toward work impressed her supervisors.","zh-TW":"她對工作的態度令主管印象深刻。"}]', NULL, NULL, 3, 145),
(146, 'attorney', '/əˈtɜːrni/', 'noun', '{"zh-TW":["律師"],"en":["a person qualified to practice law"]}', NULL, 'attorney general / defense attorney', '[{"en":"She hired an attorney.","zh-TW":"她請了一位律師。"},{"en":"The attorney general issued a statement.","zh-TW":"總檢察長發表了聲明。"}]', NULL, NULL, 3, 146),
(147, 'attract', '/əˈtrækt/', 'verb', '{"zh-TW":["吸引；招引","吸引"],"en":["to cause to come to a place or participate","to draw someone''s attention or interest"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tract","meaning":"draw/pull (拉)"},"logic":"朝向拉來，即「吸引」。"}', 'attract customers/investors/talent; attract attention / attract customers / attract investment', '[{"en":"The campaign attracted thousands of new customers.","zh-TW":"該活動吸引了數千名新客戶。"},{"en":"We need to attract top talent to remain competitive.","zh-TW":"我們需要吸引頂尖人才以保持競爭力。"},{"en":"The new store attracted many customers.","zh-TW":"新店吸引了許多顧客。"},{"en":"Bright colors attract children''s attention.","zh-TW":"鮮艷的顏色吸引孩子的注意力。"}]', '{"noun":"attraction","adjective":"attractive"}', NULL, 3, 147),
(148, 'attribute', '/əˈtrɪbjuːt/', 'verb', '{"zh-TW":["歸因於；認為是"],"en":["to regard something as being caused by"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tribute","meaning":"assign (分配)"},"logic":"朝向分配原因，即「歸因於」。"}', 'attribute success/failure to', '[{"en":"She attributes her success to hard work and determination.","zh-TW":"她將成功歸因於努力和決心。"},{"en":"The decline was attributed to market conditions.","zh-TW":"下降被歸因於市場狀況。"}]', '{"noun":"attribution"}', NULL, 3, 148),
(149, 'audience', '/ˈɔːdiəns/', 'noun', '{"zh-TW":["觀眾；聽眾"],"en":["people watching or listening to a performance"]}', NULL, 'target audience / live audience', '[{"en":"The audience applauded loudly.","zh-TW":"觀眾大聲鼓掌。"},{"en":"The show attracted a large audience.","zh-TW":"這個節目吸引了大量觀眾。"}]', NULL, NULL, 3, 149);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(150, 'audit', '/ˈɔːdɪt/', 'noun', '{"zh-TW":["審計；稽核"],"en":["an official examination of accounts or processes"]}', '{"root":{"text":"audit","meaning":"hear (聽)"},"logic":"最初為聽取帳目報告，即「審計」。"}', 'conduct an audit / annual audit', '[{"en":"The firm conducts an annual financial audit.","zh-TW":"該公司進行年度財務審計。"},{"en":"An internal audit revealed several discrepancies.","zh-TW":"內部稽核揭露了幾項差異。"}]', '{"noun":"auditor"}', NULL, 2, 150),
(151, 'authentic', '/ɔːˈθentɪk/', 'adjective', '{"zh-TW":["真實的；正宗的"],"en":["genuine; of undisputed origin"]}', '{"root":{"text":"authent","meaning":"original (原始的)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與原始真實相關的，即「正宗的」。"}', 'authentic cuisine / authentic experience', '[{"en":"This restaurant serves authentic Italian food.","zh-TW":"這家餐廳供應正宗義大利料理。"},{"en":"Is this an authentic Gucci bag?","zh-TW":"這是正品Gucci包嗎？"}]', '{"noun":"authenticity","adverb":"authentically"}', NULL, 3, 151),
(152, 'authority', '/ɔːˈθɒrəti/', 'noun', '{"zh-TW":["權威；當局"],"en":["the power to give orders","an organization with official power"]}', '{"root":{"text":"author","meaning":"originator (創始者)"},"suffix":{"text":"-ity","meaning":"state of (狀態)"},"logic":"身為創始者的地位，即「權威」。"}', 'local authority / authority figure / have authority', '[{"en":"The local authority approved the building plan.","zh-TW":"地方當局批准了建築計畫。"},{"en":"He spoke with authority on the subject.","zh-TW":"他在這個議題上很有權威。"}]', '{"adjective":"authoritative","verb":"authorize","noun2":"authorization"}', NULL, 3, 152),
(153, 'authorize', '/ˈɔːθəraɪz/', 'verb', '{"zh-TW":["授權；批准"],"en":["to give official permission for something"]}', '{"root":{"text":"author","meaning":"creator (創造者)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為有權者，即「授權」。"}', 'authorize payment/access/use', '[{"en":"Only the director can authorize expenditures over $10,000.","zh-TW":"只有主管可以授權超過10,000美元的支出。"},{"en":"The transaction was not authorized.","zh-TW":"該交易未獲授權。"}]', '{"noun":"authorization","adjective":"authorized"}', NULL, 3, 153),
(154, 'automatic', '/ˌɔːtəˈmætɪk/', 'adjective', '{"zh-TW":["自動的"],"en":["operating by itself with little human control"]}', '{"root":{"text":"auto","meaning":"self (自己)"},"suffix":{"text":"-matic","meaning":"acting (行動的)"},"logic":"自己行動的，即「自動的」。"}', 'automatic update/renewal/response; automatic transmission / automatic reply / fully automatic', '[{"en":"The system sends automatic email confirmations.","zh-TW":"系統會發送自動電子郵件確認。"},{"en":"Payments are processed automatically each month.","zh-TW":"付款每月自動處理。"},{"en":"The doors open automatically.","zh-TW":"門會自動開啟。"},{"en":"The system sends automatic reminders.","zh-TW":"系統會發送自動提醒。"}]', '{"adverb":"automatically","noun":"automation","verb":"automate"}', NULL, 3, 154),
(155, 'autumn', '/ˈɔːtəm/', 'noun', '{"zh-TW":["秋天"],"en":["the season between summer and winter"]}', NULL, 'autumn season / in autumn; in autumn / autumn leaves', '[{"en":"Sales typically increase in autumn.","zh-TW":"銷售額通常在秋季增加。"},{"en":"The autumn collection launches next week.","zh-TW":"秋季系列下週發布。"},{"en":"Leaves change color in autumn.","zh-TW":"秋天葉子會變色。"},{"en":"Autumn is my favorite season.","zh-TW":"秋天是我最喜歡的季節。"}]', '{"noun":"autumn","adjective":"autumnal"}', NULL, 2, 155),
(156, 'available', '/əˈveɪləbl/', 'adjective', '{"zh-TW":["可用的；可獲得的"],"en":["able to be used or obtained"]}', '{"root":{"text":"avail","meaning":"be strong/be of use (有用)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠被使用的，即「可用的」。"}', 'available for / currently available', '[{"en":"The product is now available in all major stores.","zh-TW":"該產品現已在所有主要商店有售。"},{"en":"I''m available for a meeting on Thursday afternoon.","zh-TW":"我週四下午有空開會。"}]', '{"noun":"availability"}', NULL, 3, 156),
(157, 'avalanche', '/ˈævəlæntʃ/', 'noun', '{"zh-TW":["雪崩"],"en":["a mass of snow falling rapidly down a mountainside"]}', '{"root":{"text":"avalanche","meaning":"descend (滑落)"},"logic":"源自法語 avaler（下降），指雪的快速滑落。"}', 'trigger an avalanche / avalanche warning', '[{"en":"The avalanche buried the entire village.","zh-TW":"雪崩掩埋了整個村莊。"},{"en":"Skiers should be aware of avalanche risks.","zh-TW":"滑雪者應注意雪崩風險。"}]', NULL, NULL, 3, 157),
(158, 'avoid', '/əˈvɔɪd/', 'verb', '{"zh-TW":["避免；迴避"],"en":["to keep away from or stop oneself from doing"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"void","meaning":"empty (空)"},"logic":"使離開空虛（危險），即「避免」。"}', 'avoid risk/mistakes/delays', '[{"en":"To avoid delays, please submit your documents early.","zh-TW":"為避免延遲，請提早提交文件。"},{"en":"The company took steps to avoid further losses.","zh-TW":"公司採取措施避免進一步損失。"}]', '{"adjective":"avoidable","noun":"avoidance"}', NULL, 2, 158),
(159, 'awake', '/əˈweɪk/', 'adjective', '{"zh-TW":["醒著的"],"en":["not sleeping"]}', NULL, 'wide awake / stay awake', '[{"en":"Are you still awake?","zh-TW":"你還醒著嗎？"},{"en":"I lay awake all night.","zh-TW":"我整晚都醒著。"}]', '{"verb":"awaken"}', NULL, 2, 159),
(160, 'award', '/əˈwɔːrd/', 'noun', '{"zh-TW":["獎項；獎金","授予","獎；獎項"],"en":["a prize given for achievement","to officially give something as a reward"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"ward","meaning":"guard/watch (看守)"},"logic":"朝向看守評定後給予，即「獎項」。"}', 'award a contract/prize/grant; award ceremony / win an award', '[{"en":"The contract was awarded to the lowest bidder.","zh-TW":"合約授予了最低出價者。"},{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲得獎項。"},{"en":"She won an award for best actress.","zh-TW":"她獲得了最佳女主角獎。"},{"en":"The awards ceremony is tonight.","zh-TW":"頒獎典禮今晚舉行。"}]', '{"verb":"award"}', NULL, 2, 160),
(161, 'baby', '/ˈbeɪbi/', 'noun', '{"zh-TW":["嬰兒；寶寶"],"en":["a very young child"]}', NULL, 'have a baby / baby products; baby shower / have a baby; baby shower / baby boom', '[{"en":"She is on maternity leave after having a baby.","zh-TW":"她生完孩子後在休產假。"},{"en":"Baby products are on the second floor.","zh-TW":"嬰兒用品在二樓。"},{"en":"The baby is sleeping.","zh-TW":"寶寶正在睡覺。"},{"en":"They''re having a baby next month.","zh-TW":"他們下個月要生寶寶了。"},{"en":"The baby is sleeping.","zh-TW":"寶寶在睡覺。"},{"en":"She''s expecting a baby in June.","zh-TW":"她預計六月生寶寶。"}]', '{"noun":"baby","adjective":"babyish"}', NULL, 1, 161),
(162, 'back', '/bæk/', 'noun', '{"zh-TW":["背部；後面","背部；後面；回去；支持"],"en":["the rear part of the body or thing","the rear part; to a previous position; to support"]}', NULL, 'go back / back and forth; go back / back up / at the back of', '[{"en":"My back hurts.","zh-TW":"我的背很痛。"},{"en":"I''ll be back in an hour.","zh-TW":"我一小時後回來。"},{"en":"He sat at the back of the room.","zh-TW":"他坐在房間後面。"},{"en":"I''ll be back in five minutes.","zh-TW":"我五分鐘後回來。"}]', '{"noun":"background, backup","adjective":"backward"}', NULL, 1, 162),
(163, 'bad', '/bæd/', 'adjective', '{"zh-TW":["壞的；糟糕的","壞的；糟糕的；嚴重的"],"en":["of poor quality; unpleasant","of poor quality; unpleasant; serious"]}', NULL, 'not bad / go bad; go bad (變壞) / not bad (還不錯)', '[{"en":"The weather is really bad today.","zh-TW":"今天天氣真的很糟。"},{"en":"The milk has gone bad.","zh-TW":"牛奶壞了。"},{"en":"The weather was really bad yesterday.","zh-TW":"昨天天氣真的很糟。"},{"en":"I feel bad about what happened.","zh-TW":"我對發生的事感到抱歉。"}]', '{"adverb":"badly","noun":"badness"}', NULL, 1, 163),
(164, 'bag', '/bæɡ/', 'noun', '{"zh-TW":["袋子；包","袋子；手提包"],"en":["a container made of flexible material","a container made of paper, plastic, cloth, or leather"]}', NULL, 'shopping bag / bag of tricks; shopping bag / handbag / luggage bag', '[{"en":"She put the books in her bag.","zh-TW":"她把書放進了包裡。"},{"en":"Can I have a plastic bag?","zh-TW":"可以給我一個塑膠袋嗎？"},{"en":"She put the groceries in a bag.","zh-TW":"她把雜貨放進袋子裡。"},{"en":"Don''t forget your bag.","zh-TW":"別忘了你的包。"}]', NULL, NULL, 1, 164),
(165, 'bail', '/beɪl/', 'noun', '{"zh-TW":["保釋金"],"en":["money paid to release someone from jail before trial"]}', NULL, 'post bail / bail out', '[{"en":"The judge set bail at $50,000.","zh-TW":"法官將保釋金定為五萬美元。"},{"en":"His family posted bail.","zh-TW":"他的家人交了保釋金。"}]', NULL, NULL, 1, 165),
(166, 'balance', '/ˈbæləns/', 'noun', '{"zh-TW":["平衡；餘額"],"en":["an even distribution of weight","the amount of money remaining in an account"]}', '{"root":{"text":"bi","meaning":"two (二)"},"suffix":{"text":"-lance","meaning":"plate (盤)"},"logic":"兩個盤子的均衡，即「平衡」。"}', 'balance sheet / maintain balance / account balance', '[{"en":"Please check your account balance before making a transfer.","zh-TW":"轉帳前請確認帳戶餘額。"},{"en":"We must maintain a balance between cost and quality.","zh-TW":"我們必須在成本和品質之間保持平衡。"}]', '{"adjective":"balanced"}', NULL, 3, 166),
(167, 'ball', '/bɔːl/', 'noun', '{"zh-TW":["球；舞會"],"en":["a round object used in games"]}', NULL, 'ball game / have a ball', '[{"en":"Throw the ball to me.","zh-TW":"把球丟給我。"},{"en":"They had a ball at the party.","zh-TW":"他們在派對上玩得很開心。"}]', NULL, NULL, 1, 167),
(168, 'ballet', '/bæˈleɪ/', 'noun', '{"zh-TW":["芭蕾舞"],"en":["a form of artistic dancing"]}', NULL, 'ballet dancer / ballet class', '[{"en":"She has studied ballet since age five.","zh-TW":"她從五歲開始學芭蕾。"},{"en":"We saw a beautiful ballet performance.","zh-TW":"我們看了一場美麗的芭蕾表演。"}]', NULL, NULL, 2, 168),
(169, 'ballot', '/ˈbælət/', 'noun', '{"zh-TW":["選票；投票"],"en":["a piece of paper used to vote"]}', NULL, 'secret ballot / ballot box', '[{"en":"Voters cast their ballots.","zh-TW":"選民投下了他們的選票。"},{"en":"The election was decided by ballot.","zh-TW":"選舉以投票方式決定。"}]', NULL, NULL, 2, 169),
(170, 'ban', '/bæn/', 'verb', '{"zh-TW":["禁止；禁令"],"en":["to officially prohibit something"]}', '{"root":{"text":"ban","meaning":"proclaim/forbid (宣告/禁止)"},"logic":"宣告禁止，即「禁止」。"}', 'ban on / impose a ban', '[{"en":"The city imposed a ban on single-use plastics.","zh-TW":"該市對一次性塑膠實施禁令。"},{"en":"Smoking is banned in all public buildings.","zh-TW":"所有公共建築內禁止吸菸。"}]', NULL, NULL, 1, 170),
(171, 'band', '/bænd/', 'noun', '{"zh-TW":["樂隊；帶子"],"en":["a group of musicians"]}', NULL, 'rock band / rubber band', '[{"en":"He plays guitar in a band.","zh-TW":"他在樂隊裡彈吉他。"},{"en":"The band performed live on stage.","zh-TW":"樂隊在舞台上現場演出。"}]', NULL, NULL, 1, 171),
(172, 'bandwidth', '/ˈbændwɪdθ/', 'noun', '{"zh-TW":["頻寬"],"en":["the amount of data that can be transmitted"]}', NULL, 'high bandwidth / bandwidth limit', '[{"en":"We need more bandwidth for video calls.","zh-TW":"我們需要更多頻寬進行視訊通話。"},{"en":"The server has limited bandwidth.","zh-TW":"伺服器頻寬有限。"}]', NULL, NULL, 3, 172),
(173, 'bank', '/bæŋk/', 'noun', '{"zh-TW":["銀行；河岸"],"en":["a financial institution","a financial institution; the side of a river"]}', NULL, 'bank account / river bank; bank account / bank transfer / river bank', '[{"en":"I need to go to the bank.","zh-TW":"我需要去銀行。"},{"en":"We sat on the river bank.","zh-TW":"我們坐在河岸上。"},{"en":"They sat on the river bank.","zh-TW":"他們坐在河岸上。"}]', '{"noun2":"banker","noun3":"banking","noun":"banker, banking"}', NULL, 1, 173),
(174, 'bankrupt', '/ˈbæŋkrʌpt/', 'adjective', '{"zh-TW":["破產的"],"en":["unable to pay debts"]}', NULL, 'go bankrupt / declare bankrupt', '[{"en":"The company went bankrupt.","zh-TW":"公司破產了。"},{"en":"He was declared bankrupt by the court.","zh-TW":"他被法院宣告破產。"}]', '{"noun":"bankruptcy"}', NULL, 3, 174),
(175, 'bar', '/bɑːr/', 'noun', '{"zh-TW":["酒吧；條；障礙"],"en":["a place serving drinks; a long narrow piece"]}', NULL, 'behind bars / bar chart', '[{"en":"Let''s meet at the bar.","zh-TW":"我們在酒吧見面吧。"},{"en":"He was put behind bars.","zh-TW":"他被關進了監獄。"}]', '{"verb":"bar","noun2":"bartender"}', NULL, 1, 175),
(176, 'barely', '/ˈbeərli/', 'adverb', '{"zh-TW":["勉強；幾乎不"],"en":["only just; almost not"]}', '{"root":{"text":"bare","meaning":"bare/merely (僅僅)"},"suffix":{"text":"-ly","meaning":"in manner of (以…方式)"},"logic":"僅僅的方式，即「勉強」。"}', 'barely visible / barely enough / can barely', '[{"en":"She barely passed the exam.","zh-TW":"她勉強通過了考試。"},{"en":"I can barely hear you.","zh-TW":"我幾乎聽不到你說話。"}]', NULL, NULL, 2, 176),
(177, 'bargain', '/ˈbɑːrɡɪn/', 'noun', '{"zh-TW":["便宜貨；協議","討價還價","便宜貨；交易"],"en":["something bought cheaply","an agreement between parties","to negotiate terms of a deal"]}', '{"root":{"text":"bargain","meaning":"trade/negotiate (交易)"},"logic":"通過交易談判達成的，即「便宜貨、協議」。"}', 'bargain price / collective bargaining; a real bargain / bargain hunter', '[{"en":"The property was a real bargain at that price.","zh-TW":"以那個價格買下這處房產真是便宜。"},{"en":"The union engaged in collective bargaining.","zh-TW":"工會進行了集體談判。"},{"en":"This coat was a real bargain at half price.","zh-TW":"這件外套半價，真是便宜貨。"},{"en":"They bargained with the vendor for a lower price.","zh-TW":"他們跟攤販討價還價。"}]', '{"verb":"bargain"}', NULL, 3, 177),
(178, 'barrier', '/ˈbæriər/', 'noun', '{"zh-TW":["障礙；壁壘","障礙；屏障"],"en":["a fence or obstacle that prevents movement or access","something that prevents movement or access"]}', '{"root":{"text":"bar","meaning":"bar/block (阻擋)"},"suffix":{"text":"-ier","meaning":"thing that (…的東西)"},"logic":"阻擋的東西，即「障礙」。"}', 'trade barrier / language barrier / barrier to entry; language barrier / trade barrier / break down barriers', '[{"en":"Language barriers can hinder international business.","zh-TW":"語言障礙可能妨礙國際商務。"},{"en":"The company faced significant barriers to entry.","zh-TW":"公司面臨重大的進入門檻。"},{"en":"Language can be a barrier to communication.","zh-TW":"語言可能是溝通的障礙。"},{"en":"They are trying to break down trade barriers.","zh-TW":"他們正試圖消除貿易障礙。"}]', NULL, NULL, 3, 178),
(179, 'base', '/beɪs/', 'noun', '{"zh-TW":["基礎；基地","以…為基礎"],"en":["the lowest part or foundation","to use as a starting point"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"logic":"底部基礎，即「基礎」。"}', 'customer base / base on / base salary', '[{"en":"The company has a large customer base in Asia.","zh-TW":"公司在亞洲擁有龐大的客戶群。"},{"en":"The decision was based on thorough research.","zh-TW":"該決定基於深入研究。"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 1, 179),
(180, 'basic', '/ˈbeɪsɪk/', 'adjective', '{"zh-TW":["基本的；基礎的"],"en":["forming the most important part"]}', NULL, 'basic knowledge / basic needs', '[{"en":"You need basic computer skills.","zh-TW":"你需要基本的電腦技能。"},{"en":"Food and water are basic needs.","zh-TW":"食物和水是基本需求。"}]', '{"noun":"basics","adverb":"basically"}', NULL, 2, 180),
(181, 'basis', '/ˈbeɪsɪs/', 'noun', '{"zh-TW":["基礎；依據","基礎；根據"],"en":["the underlying support or foundation for something","the underlying support or foundation"]}', '{"root":{"text":"bas","meaning":"bottom (底部)"},"suffix":{"text":"-is","meaning":"noun ending (名詞字尾)"},"logic":"底部的根基，即「基礎」。"}', 'on a regular basis / on the basis of; on the basis of / daily basis / regular basis', '[{"en":"Reports are submitted on a weekly basis.","zh-TW":"報告每週提交一次。"},{"en":"Candidates are selected on the basis of experience.","zh-TW":"候選人根據經驗進行篩選。"},{"en":"Employees are evaluated on a regular basis.","zh-TW":"員工定期接受評估。"},{"en":"On what basis did you make that decision?","zh-TW":"你根據什麼做出那個決定？"}]', '{"adjective":"basic","adverb":"basically"}', NULL, 2, 181),
(182, 'bath', '/bæθ/', 'noun', '{"zh-TW":["洗澡；浴缸","沐浴；浴缸"],"en":["an act of washing the body","washing the body; a container for water"]}', NULL, 'take a bath / bath towel; take a bath / bathroom', '[{"en":"I take a bath every evening.","zh-TW":"我每天晚上洗澡。"},{"en":"The bath is full of hot water.","zh-TW":"浴缸裡滿是熱水。"},{"en":"The bathroom is on the second floor.","zh-TW":"浴室在二樓。"}]', '{"verb":"bathe","noun2":"bathroom"}', NULL, 1, 182),
(183, 'battle', '/ˈbætəl/', 'noun', '{"zh-TW":["戰鬥；鬥爭"],"en":["a fight between armed forces"]}', NULL, 'battle against / battle field', '[{"en":"The battle lasted three days.","zh-TW":"戰鬥持續了三天。"},{"en":"She won her battle against cancer.","zh-TW":"她贏得了與癌症的鬥爭。"}]', '{"verb":"battle"}', NULL, 2, 183),
(184, 'beach', '/biːtʃ/', 'noun', '{"zh-TW":["海灘"],"en":["an area of sand beside the sea"]}', NULL, 'on the beach / beach volleyball', '[{"en":"We spent the day at the beach.","zh-TW":"我們在海灘度過了一天。"},{"en":"The beach was crowded in summer.","zh-TW":"夏天海灘很擁擠。"}]', NULL, NULL, 2, 184),
(185, 'bear', '/beər/', 'verb', '{"zh-TW":["承擔；忍受","攜帶","忍受；承擔"],"en":["to carry or support the weight of","to endure or tolerate","to accept or endure something"]}', '{"root":{"text":"bear","meaning":"carry (攜帶)"},"logic":"攜帶重量，即「承擔」。"}', 'bear responsibility / bear in mind; bear in mind / can''t bear', '[{"en":"The company will bear the cost of relocation.","zh-TW":"公司將承擔搬遷費用。"},{"en":"Please bear in mind the deadline is Friday.","zh-TW":"請記住截止日期是週五。"},{"en":"I can''t bear the noise.","zh-TW":"我受不了這噪音。"},{"en":"Bear in mind that it''s expensive.","zh-TW":"記住它很貴。"}]', '{"adjective":"bearable"}', NULL, 1, 185),
(186, 'beat', '/biːt/', 'verb', '{"zh-TW":["打敗；跳動"],"en":["to defeat someone; to make a rhythm"]}', NULL, 'beat the record / heartbeat', '[{"en":"Our team beat theirs 3-1.","zh-TW":"我們隊以3比1打敗了他們。"},{"en":"My heart was beating fast.","zh-TW":"我的心跳得很快。"}]', '{"noun":"beat"}', NULL, 1, 186),
(187, 'beautiful', '/ˈbjuːtɪfəl/', 'adjective', '{"zh-TW":["美麗的","美麗的；漂亮的","美麗的；美好的"],"en":["very pleasing to look at or experience","very attractive or pleasing","very attractive; giving great pleasure"]}', NULL, 'beautiful weather / beautiful design; beautiful scenery / beautiful day; beautiful scenery/weather/music', '[{"en":"The office has a beautiful view.","zh-TW":"辦公室有很美的景觀。"},{"en":"Thank you for this beautiful gift.","zh-TW":"謝謝你這份美麗的禮物。"},{"en":"What a beautiful sunset!","zh-TW":"多美的日落啊！"},{"en":"She has a beautiful voice.","zh-TW":"她有一副美麗的嗓音。"},{"en":"What a beautiful day!","zh-TW":"多麼美好的一天！"},{"en":"She wore a beautiful dress.","zh-TW":"她穿了一件漂亮的洋裝。"}]', '{"adjective":"beautiful","noun":"beauty","adverb":"beautifully","verb":"beautify"}', NULL, 3, 187),
(188, 'because', '/bɪˈkɒz/', 'conjunction', '{"zh-TW":["因為"],"en":["for the reason that"]}', NULL, 'because of / just because', '[{"en":"I stayed home because I was sick.","zh-TW":"我因為生病待在家裡。"},{"en":"The game was canceled because of rain.","zh-TW":"比賽因為下雨被取消了。"}]', NULL, NULL, 3, 188),
(189, 'become', '/bɪˈkʌm/', 'verb', '{"zh-TW":["變成；成為","成為；變得"],"en":["to begin to be; to grow to be","to begin to be something","to begin to be; to start being"]}', NULL, 'become aware / become available; become aware / become friends; become + adj/noun', '[{"en":"He became the new manager.","zh-TW":"他成為了新經理。"},{"en":"The product has become very popular.","zh-TW":"這個產品變得非常受歡迎。"},{"en":"She became a doctor.","zh-TW":"她成為了一名醫生。"},{"en":"It''s becoming colder.","zh-TW":"天氣越來越冷了。"},{"en":"The situation became worse.","zh-TW":"情況變得更糟了。"}]', '{"verb":"become"}', NULL, 2, 189),
(190, 'bed', '/bɛd/', 'noun', '{"zh-TW":["床","床；花壇"],"en":["a piece of furniture for sleeping","a piece of furniture for sleeping on"]}', NULL, 'go to bed / in bed; go to bed / make the bed / bed and breakfast', '[{"en":"Time to go to bed.","zh-TW":"該上床睡覺了。"},{"en":"He stayed in bed all day.","zh-TW":"他整天待在床上。"},{"en":"I usually go to bed at 11 PM.","zh-TW":"我通常晚上11點上床睡覺。"},{"en":"Please make your bed.","zh-TW":"請整理你的床。"}]', '{"noun2":"bedroom","noun3":"bedding","noun":"bedding, bedroom"}', NULL, 1, 190),
(191, 'before', '/bɪˈfɔːr/', 'preposition, conjunction, adverb', '{"zh-TW":["在...之前"],"en":["earlier than; at an earlier time"]}', NULL, 'before + V-ing / the day before', '[{"en":"Finish your work before the deadline.","zh-TW":"在截止日期前完成你的工作。"},{"en":"I''ve never been here before.","zh-TW":"我以前從未來過這裡。"}]', NULL, NULL, 2, 191),
(192, 'begin', '/bɪˈɡɪn/', 'verb', '{"zh-TW":["開始","開始；著手"],"en":["to start","to start doing something","to start; to do the first part of something"]}', NULL, 'begin with / to begin with; begin to do / begin doing / begin with', '[{"en":"The workshop begins at 10 a.m.","zh-TW":"研習會在上午10點開始。"},{"en":"Let us begin with the agenda.","zh-TW":"讓我們從議程開始。"},{"en":"The meeting begins at 9.","zh-TW":"會議9點開始。"},{"en":"Let''s begin with introductions.","zh-TW":"讓我們從自我介紹開始。"},{"en":"The meeting begins at 9 AM.","zh-TW":"會議上午九點開始。"},{"en":"Let''s begin with the first item on the agenda.","zh-TW":"讓我們從議程的第一項開始。"}]', '{"verb":"begin","noun":"beginning","noun2":"beginner"}', NULL, 2, 192),
(193, 'behalf', '/bɪˈhɑːf/', 'noun', '{"zh-TW":["代表；為了…的利益","代表"],"en":["in the interest of; as a representative of"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"half","meaning":"side (邊)"},"logic":"在某人的邊（一方），即「代表」。"}', 'on behalf of / on sb''s behalf; on behalf of / act on someone''s behalf', '[{"en":"I''m writing on behalf of the marketing department.","zh-TW":"我代表行銷部門寫信。"},{"en":"The lawyer acted on behalf of the client.","zh-TW":"律師代表客戶行事。"},{"en":"I am writing on behalf of my client.","zh-TW":"我代表我的客戶寫信。"},{"en":"She accepted the award on behalf of the team.","zh-TW":"她代表團隊接受了獎項。"}]', NULL, NULL, 2, 193),
(194, 'behave', '/bɪˈheɪv/', 'verb', '{"zh-TW":["行為；表現"],"en":["to act in a particular way","to conduct oneself properly"]}', '{"prefix":{"text":"be-","meaning":"thoroughly (徹底)"},"root":{"text":"have","meaning":"hold oneself (持有自己)"},"logic":"徹底持有自己的方式，即「行為」。"}', 'behave professionally / consumer behavior', '[{"en":"Employees are expected to behave professionally.","zh-TW":"員工應表現專業。"},{"en":"Market conditions cause consumers to behave differently.","zh-TW":"市場條件使消費者行為有所不同。"}]', '{"noun":"behavior"}', NULL, 2, 194),
(195, 'behind', '/bɪˈhaɪnd/', 'preposition', '{"zh-TW":["在…後面；落後","在…後面","在...後面；落後"],"en":["at the back of","less advanced than","at the back of; not making enough progress"]}', NULL, 'fall behind / behind schedule; behind schedule / fall behind; behind schedule / fall behind / leave behind', '[{"en":"The project is behind schedule.","zh-TW":"專案進度落後了。"},{"en":"Who is behind this decision?","zh-TW":"誰在這個決定背後？"},{"en":"The cat hid behind the sofa.","zh-TW":"貓躲在沙發後面。"},{"en":"We''re behind schedule.","zh-TW":"我們落後於進度了。"},{"en":"The garden is behind the house.","zh-TW":"花園在房子後面。"},{"en":"We''re behind schedule on this project.","zh-TW":"我們這個專案進度落後。"}]', '{"preposition":"behind","adverb":"behind"}', NULL, 2, 195),
(196, 'believe', '/bɪˈliːv/', 'verb', '{"zh-TW":["相信；認為"],"en":["to think something is true","to have confidence in","to accept as true","to think something is true; to have faith"]}', NULL, 'believe in / hard to believe; believe in / believe it or not', '[{"en":"I believe this strategy will work.","zh-TW":"我相信這個策略會成功。"},{"en":"We believe in teamwork.","zh-TW":"我們相信團隊合作。"},{"en":"I believe you''re right.","zh-TW":"我相信你是對的。"},{"en":"Do you believe in ghosts?","zh-TW":"你相信有鬼嗎？"},{"en":"I believe this plan will work.","zh-TW":"我相信這個計畫會成功。"},{"en":"She doesn''t believe in ghosts.","zh-TW":"她不相信鬼。"}]', '{"verb":"believe","noun":"belief","adjective":"believable","adjective2":"unbelievable"}', NULL, 3, 196),
(197, 'belong', '/bɪˈlɒŋ/', 'verb', '{"zh-TW":["屬於","屬於；適合在"],"en":["to be the property of","to be the property of; to be in the right place"]}', NULL, 'belong to / a sense of belonging', '[{"en":"This book belongs to me.","zh-TW":"這本書是我的。"},{"en":"She felt she didn''t belong.","zh-TW":"她覺得自己不屬於這裡。"},{"en":"These files belong in the cabinet.","zh-TW":"這些文件應該放在櫃子裡。"}]', '{"noun":"belonging"}', NULL, 2, 197),
(198, 'below', '/bɪˈloʊ/', 'preposition', '{"zh-TW":["在…下面","在...下面；低於"],"en":["at a lower level than","at a lower level than; less than"]}', NULL, 'below average / see below; below average / below zero', '[{"en":"The temperature dropped below zero.","zh-TW":"溫度降到了零度以下。"},{"en":"See the chart below.","zh-TW":"請看下面的圖表。"},{"en":"The temperature dropped below zero.","zh-TW":"氣溫降到零度以下。"},{"en":"See the chart below.","zh-TW":"請見下方圖表。"}]', NULL, NULL, 2, 198),
(199, 'benchmark', '/ˈbentʃmɑːrk/', 'noun', '{"zh-TW":["基準；標竿"],"en":["a standard or point of reference for comparison","a standard for comparison"]}', '{"root":{"text":"bench","meaning":"bench (長凳)"},"suffix":{"text":"mark","meaning":"mark (標記)"},"logic":"長凳上的標記（測量基準），即「基準」。"}', 'industry benchmark / set a benchmark / benchmark against', '[{"en":"Our service quality sets the benchmark in the industry.","zh-TW":"我們的服務品質樹立了行業基準。"},{"en":"We benchmark our performance against competitors.","zh-TW":"我們以競爭對手為基準評估績效。"},{"en":"This sets a new benchmark for quality.","zh-TW":"這為品質設立了新的標竿。"},{"en":"We measure performance against industry benchmarks.","zh-TW":"我們以產業基準來衡量績效。"}]', '{"verb":"benchmark","noun":"benchmark","noun2":"benchmarking"}', NULL, 3, 199);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(200, 'bend', '/bɛnd/', 'verb', '{"zh-TW":["彎曲；屈身"],"en":["to make something curved"]}', NULL, 'bend down / bend the rules', '[{"en":"Bend your knees slightly.","zh-TW":"稍微彎曲膝蓋。"},{"en":"She bent down to pick it up.","zh-TW":"她彎腰撿起來。"}]', NULL, NULL, 1, 200),
(201, 'beneath', '/bɪˈniːθ/', 'preposition', '{"zh-TW":["在…下方"],"en":["in or to a lower position than; under"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"neath","meaning":"below (下方)"},"logic":"在下方的位置。"}', 'beneath the surface / beneath one''s dignity', '[{"en":"The treasure was buried beneath the old tree.","zh-TW":"寶藏埋在老樹下方。"},{"en":"Beneath the surface, there are many problems.","zh-TW":"表面之下有許多問題。"}]', NULL, NULL, 3, 201),
(202, 'benefit', '/ˈbenɪfɪt/', 'noun', '{"zh-TW":["利益；好處","福利"],"en":["an advantage or profit gained","a payment made by the state or employer"]}', '{"root":{"text":"bene","meaning":"good (好)"},"suffix":{"text":"-fit","meaning":"do/make (做)"},"logic":"做好事帶來的，即「利益」。"}', 'benefit from / employee benefits / mutual benefit', '[{"en":"Both parties will benefit from this partnership.","zh-TW":"雙方都將從這個合作中受益。"},{"en":"The company offers excellent employee benefits.","zh-TW":"公司提供優秀的員工福利。"}]', '{"adjective":"beneficial"}', NULL, 3, 202),
(203, 'beside', '/bɪˈsaɪd/', 'preposition', '{"zh-TW":["在…旁邊"],"en":["next to; at the side of"]}', NULL, 'beside the point / sit beside', '[{"en":"Come and sit beside me.","zh-TW":"來坐在我旁邊。"},{"en":"That''s beside the point.","zh-TW":"那不是重點。"}]', NULL, NULL, 2, 203),
(204, 'besides', '/bɪˈsaɪdz/', 'preposition', '{"zh-TW":["除了…之外"],"en":["in addition to; apart from"]}', '{"prefix":{"text":"be-","meaning":"by (在旁)"},"root":{"text":"sides","meaning":"sides (邊)"},"logic":"在旁邊之外還有，即「除了…之外」。"}', 'besides that / besides me', '[{"en":"Besides English, she speaks French and German.","zh-TW":"除了英語，她還會說法語和德語。"},{"en":"Besides the cost, there are other concerns.","zh-TW":"除了費用之外，還有其他顧慮。"}]', NULL, NULL, 3, 204),
(205, 'best', '/best/', 'adjective, adverb, noun', '{"zh-TW":["最好的；最佳地"],"en":["of the highest quality; most well"]}', NULL, 'do one''s best / at best / best practice', '[{"en":"She is the best student in class.","zh-TW":"她是班上最好的學生。"},{"en":"We did our best to finish on time.","zh-TW":"我們盡了最大努力準時完成。"}]', NULL, NULL, 1, 205),
(206, 'beta', '/ˈbeɪtə/', 'noun', '{"zh-TW":["測試版"],"en":["an early version of a product for testing"]}', NULL, 'beta version / beta testing', '[{"en":"The app is still in beta.","zh-TW":"這個應用程式還在測試階段。"},{"en":"Beta testers found several bugs.","zh-TW":"測試用戶發現了幾個錯誤。"}]', NULL, NULL, 1, 206),
(207, 'better', '/ˈbetər/', 'adjective, adverb', '{"zh-TW":["更好的；更好地"],"en":["of a higher standard; more well"]}', NULL, 'had better (最好...) / get better', '[{"en":"This solution is better than the last one.","zh-TW":"這個方案比上一個好。"},{"en":"You''d better leave now.","zh-TW":"你最好現在離開。"}]', '{"verb":"better"}', NULL, 2, 207),
(208, 'between', '/bɪˈtwiːn/', 'preposition', '{"zh-TW":["在…之間","在...之間（兩者）"],"en":["in the space or time separating two things","in the space separating two things"]}', NULL, 'between meetings / in between; between you and me / in between; between A and B / in between', '[{"en":"The interview is between 2 and 3 p.m.","zh-TW":"面試在下午2點到3點之間。"},{"en":"Choose between the two options.","zh-TW":"在兩個選項之間做選擇。"},{"en":"The shop is between the bank and the post office.","zh-TW":"商店在銀行和郵局之間。"},{"en":"Between you and me, I don''t like him.","zh-TW":"你我之間說，我不喜歡他。"},{"en":"The meeting is between 2 and 4 PM.","zh-TW":"會議在下午2點到4點之間。"}]', '{"preposition":"between"}', NULL, 3, 208),
(209, 'beyond', '/bɪˈjɒnd/', 'preposition', '{"zh-TW":["超越；在…之外"],"en":["further away than; outside the limits of"]}', '{"prefix":{"text":"be-","meaning":"by (在)"},"root":{"text":"yond","meaning":"that side (那邊)"},"logic":"在那邊之外，即「超越」。"}', 'beyond expectations / beyond doubt / go beyond', '[{"en":"The results went beyond our expectations.","zh-TW":"結果超出了我們的預期。"},{"en":"This task is beyond my abilities.","zh-TW":"這項任務超出了我的能力。"}]', NULL, NULL, 2, 209),
(210, 'bid', '/bɪd/', 'noun', '{"zh-TW":["出價；投標"],"en":["an offer of a price for something","an attempt to achieve something"]}', '{"root":{"text":"bid","meaning":"offer (提供)"},"logic":"提供價格，即「出價」。"}', 'submit a bid / highest bidder', '[{"en":"Three companies submitted bids for the project.","zh-TW":"三家公司對該專案提交了投標。"},{"en":"The winning bid was $4.5 million.","zh-TW":"中標金額為450萬美元。"}]', '{"noun":"bidder"}', NULL, 1, 210),
(211, 'big', '/bɪɡ/', 'adjective', '{"zh-TW":["大的","大的；重要的"],"en":["of considerable size or extent","large in size; important"]}', NULL, 'big deal / big picture; a big deal / big business', '[{"en":"They live in a big house.","zh-TW":"他們住在一棟大房子裡。"},{"en":"It''s no big deal.","zh-TW":"這沒什麼大不了的。"},{"en":"This is a big decision.","zh-TW":"這是一個重大決定。"}]', NULL, NULL, 1, 211),
